using System.Linq;using MultiFPS.Gameplay;using MultiFPS.UI;using ROM.UI.Sprint01;using UnityEngine;using UnityEngine.UI;
namespace ROM.UI.Gameplay {public sealed partial class RiftGameplayHUD {
 void Start(){if(Coordinates)Coordinates.gameObject.SetActive(false);var field=FindFirstObjectByType<RiftFieldUI>();if(field){foreach(var g in field.PotionRoot.GetComponentsInChildren<RiftHUDGraphic>(true)){g.Border=new Color(.41f,.35f,.53f);g.SetVerticesDirty();}var rect=(RectTransform)field.MapButton.transform;rect.anchoredPosition=new Vector2(-145,-254);var old=field.MapButton.GetComponent<RiftHUDGraphic>();if(old)old.enabled=false;var chrome=new GameObject("Modern map access chrome",typeof(RectTransform)).GetComponent<RectTransform>();chrome.SetParent(field.MapButton.transform,false);chrome.anchorMin=Vector2.zero;chrome.anchorMax=Vector2.one;chrome.sizeDelta=Vector2.zero;chrome.anchoredPosition=Vector2.zero;chrome.SetAsFirstSibling();var surface=chrome.gameObject.AddComponent<RiftMapSurface>();surface.Fill=new Color(.04f,.035f,.065f,.8f);surface.Border=new Color(.46f,.36f,.65f);surface.raycastTarget=true;field.MapButton.targetGraphic=surface;foreach(var text in field.MapButton.GetComponentsInChildren<Text>())text.color=new Color(.92f,.9f,.97f);}}
 static void DockRect(RectTransform rect,Vector2 anchor,Vector2 pivot,Vector2 position){if(!rect)return;rect.anchorMin=rect.anchorMax=anchor;rect.pivot=pivot;rect.anchoredPosition=position;}
 void StyleGeneralShortcut(Button button,int index){
  var old=button.GetComponent<RiftHUDGraphic>();if(old)old.enabled=false;
  var oldIcon=button.transform.Find("Gold icon");if(oldIcon)oldIcon.gameObject.SetActive(false);
  var frame=new GameObject("General action surface",typeof(RectTransform)).GetComponent<RectTransform>();frame.SetParent(button.transform,false);frame.anchorMin=Vector2.zero;frame.anchorMax=Vector2.one;frame.anchoredPosition=frame.sizeDelta=Vector2.zero;frame.SetAsFirstSibling();var surface=frame.gameObject.AddComponent<RiftMapSurface>();surface.Fill=new Color(.055f,.05f,.085f,.9f);surface.Border=new Color(.55f,.43f,.72f,.95f);surface.Radius=7;surface.raycastTarget=true;button.targetGraphic=surface;
  var colors=button.colors;colors.normalColor=Color.white;colors.highlightedColor=new Color(.85f,.76f,1);colors.selectedColor=colors.highlightedColor;button.colors=colors;
  var icon=new GameObject("Readable general action icon",typeof(RectTransform)).GetComponent<RectTransform>();icon.SetParent(button.transform,false);icon.anchorMin=icon.anchorMax=icon.pivot=new Vector2(.5f,.5f);icon.sizeDelta=new Vector2(25,25);icon.anchoredPosition=Vector2.zero;
  if(index==5){for(int line=0;line<3;line++){var row=new GameObject("Journal entry line",typeof(RectTransform)).GetComponent<RectTransform>();row.SetParent(icon,false);row.anchorMin=row.anchorMax=row.pivot=new Vector2(.5f,.5f);row.sizeDelta=new Vector2(line==2?14:22,2);row.anchoredPosition=new Vector2(line==2?-4:0,8-line*8);var graphic=row.gameObject.AddComponent<Image>();graphic.color=new Color(.93f,.9f,1);graphic.raycastTarget=false;}}
  else{var graphic=icon.gameObject.AddComponent<RiftHUDGraphic>();graphic.Shape=index==3?HUDShape.Gear:index==6?HUDShape.Crystal:HUDShape.Target;graphic.color=new Color(.93f,.9f,1);graphic.Thickness=1.5f;graphic.raycastTarget=false;}
 }
 void ModernizeLayout(){
  ResourceFill.color=new Color(.85f,.25f,.06f);ResourceFill.Border=new Color(.41f,.35f,.53f);
  foreach(var g in GetComponentsInChildren<RiftHUDGraphic>(true)){g.Border=new Color(.4f,.36f,.53f,.8f);if(g.Shape==HUDShape.Bar||g.GetComponent<Mask>())continue;g.Bottom=new Color(.035f,.038f,.06f,.72f);g.color=g.Shape==HUDShape.Line||g.Shape==HUDShape.Ornament?new Color(.43f,.34f,.59f,.7f):g.Shape==HUDShape.Panel||g.Shape==HUDShape.Slot?new Color(.14f,.12f,.2f,.86f):new Color(.83f,.78f,.95f);g.SetVerticesDirty();}
  foreach(var text in GetComponentsInChildren<Text>(true))if(text.color==Theme.Gold||text.color==Theme.BrightGold||text.color==Theme.Text)text.color=new Color(.91f,.9f,.96f);
  var region=Design.Find("Zone and checkpoint");if(region)region.gameObject.SetActive(false); // Existing balance stays in inventory; coordinates were diagnostic chrome.
  if(bagButtonLabel)bagButtonLabel.transform.parent.gameObject.SetActive(false); // Reuse existing inventory shortcut instead of duplicate giant BOLSA button.
  var shortcuts=Design.Find("Gameplay shortcuts") as RectTransform;
  if(shortcuts){DockRect(shortcuts,new Vector2(.5f,0),new Vector2(.5f,0),new Vector2(0,196));shortcuts.sizeDelta=new Vector2(198,46);var general=new GameObject("General menu shortcuts",typeof(RectTransform)).GetComponent<RectTransform>();general.SetParent(Design,false);DockRect(general,Vector2.one,Vector2.one,new Vector2(-326,-24));general.sizeDelta=new Vector2(220,44);int personalIndex=0,generalIndex=0;
   var buttons=shortcuts.GetComponentsInChildren<Button>(true);for(int i=0;i<buttons.Length;i++){var button=buttons[i];var cap=i<ShortcutLabels.Length?ShortcutLabels[i]:null;if(i==1){button.gameObject.SetActive(false);if(cap)cap.gameObject.SetActive(false);continue;}bool personal=i==0||i==2||i==4;var rect=(RectTransform)button.transform;rect.SetParent(personal?shortcuts:general,false);rect.anchorMin=rect.anchorMax=new Vector2(0,1);rect.pivot=new Vector2(0,1);rect.localScale=Vector3.one;rect.sizeDelta=new Vector2(46,42);rect.anchoredPosition=new Vector2((personal?personalIndex++:generalIndex++)*54,0);if(cap){cap.transform.SetParent(button.transform,false);DockRect(cap.rectTransform,new Vector2(.5f,0),new Vector2(.5f,1),new Vector2(0,-3));cap.rectTransform.sizeDelta=new Vector2(64,20);cap.fontSize=12;cap.rectTransform.localScale=Vector3.one;}if(!personal)StyleGeneralShortcut(button,i);if(i==3){rect.sizeDelta=new Vector2(36,36);rect.anchoredPosition+=new Vector2(5,-3);if(cap){cap.fontSize=11;cap.rectTransform.sizeDelta=new Vector2(54,18);}}}
   foreach(Transform child in shortcuts)if(child.GetComponent<Text>())child.gameObject.SetActive(false);
  }
  var tracker=Design.Find("Tracked quest") as RectTransform;DockRect(tracker,Vector2.up,Vector2.up,new Vector2(24,-24));
  DockRect(TargetPanel,Vector2.one,Vector2.one,new Vector2(-54,-350));TargetPanel.sizeDelta=new Vector2(396,112);var targetSurface=TargetPanel.gameObject.AddComponent<RiftMapSurface>();targetSurface.Fill=new Color(.03f,.034f,.055f,.79f);targetSurface.Border=new Color(.41f,.35f,.56f,.8f);targetSurface.raycastTarget=false;
  if(Portrait){var self=Portrait.GetComponent<Button>();if(!self)self=Portrait.gameObject.AddComponent<Button>();self.targetGraphic=Portrait;Portrait.raycastTarget=true;self.onClick.AddListener(()=>{var input=RiftMMOController.Instance;if(input&&input.Actor)input.Select(input.Actor.Health);});var tip=Portrait.GetComponent<RiftTooltipTrigger>();if(!tip)tip=Portrait.gameObject.AddComponent<RiftTooltipTrigger>();tip.Title="Seleccionarte";tip.Description="Mostrá tu objetivo y estado.";tip.ActionId="SelfTarget";}
 }
